import { defineNode, inPort, outPort } from '../_kit/defineNode.js'

/**
 * Mentoring Distribution node (design 01 section 3.7, 02 sections 4/12, 03 section 9.4, 04 sections 3.10/3.17): the fixed timetable of the
 * offline 1-1 sessions in the training hall (mentor x round x day -> company), generated by ONE deterministic algorithm, editable by
 * hand, published through two views and a server-timestamp countdown.
 * Ports mirror `node_types.distribution` (m02): in `mentors` + `companies` (Lists' `items`, by reference), optional `schedule` (an Agenda's
 * days: dates by reference, decision 02-12; without it the node keeps its own day config); out `sessions-tab` (the matrix, an Agenda
 * tab) and `my-meetings-tab` ("My schedule / Who do I meet next", an Agenda tab). The two standalone surfaces are routes
 * (`/view/:ref/matrix`, `/view/:ref/live`) fed by `public_links` of kind `view`.
 */
export default defineNode({
  key: 'distribution',
  version: 1,
  name: { en: 'Mentoring distribution', ar: 'توزيع المنتورينج' },
  icon: 'distribution',
  category: 'operations',
  // kept inline (= distributionLogic.defaultDistributionConfig): the manifest is in the routes chunk and must stay tiny
  defaultConfig: () => ({ timer: { alertSeconds: 7, sounds: true } }),
  configSchema: { type: 'object', properties: { timer: { type: 'object' } } },
  ports: {
    in: [
      inPort('mentors', ['rows:list-item'], { en: 'Mentors', ar: 'المنتورز' }, { kind: 'expert', required: true }),
      inPort('companies', ['rows:list-item'], { en: 'Companies', ar: 'الشركات' }, { kind: 'company', required: true }),
      inPort('schedule', ['schedule'], { en: 'Schedule', ar: 'الجدول' }, { cardinality: 'one' }),
    ],
    out: [
      outPort('sessions-tab', ['view'], { en: 'Sessions tab', ar: 'تبويب الجلسات' }),
      outPort('my-meetings-tab', ['view'], { en: 'My meetings tab', ar: 'تبويب اجتماعاتي' }),
    ],
  },
  contributesViews: [
    { key: 'sessions-tab', title: { en: 'Distribution', ar: 'التوزيع' }, component: () => import('./MatrixTab.jsx') },
    { key: 'my-meetings-tab', title: { en: 'My schedule', ar: 'جدولي' }, component: () => import('./MyScheduleTab.jsx') },
  ],
  visibility: { supported: ['private', 'platform', 'public'], showToParticipants: true },
  components: {
    Edit: () => import('./Edit.jsx'),
    View: () => import('./View.jsx'),
    Settings: () => import('./Settings.jsx'),
  },
  ownsTables: ['distributions', 'distribution_days', 'distribution_day_mentors', 'distribution_mentor_rules', 'distribution_sessions', 'distribution_timers'],
})
